// Keeps two generated files in step with the Exomem repo.
//
//   npm run sync:instruction-blocks -- <path-to-exomem-repo>
//     Copies the assistant instruction blocks from docs/prominence.md into
//     src/app/exomem/home/instruction-blocks.generated.ts, and the Cloud
//     transfer tools' names and actions from tests/fixtures/mcp_cloud_only_tool_schemas.json
//     into src/exomem-gateway/cloud-transfer-tools.generated.ts. Both record
//     the Exomem commit they came from.
//
//   npm run sync:instruction-blocks -- --check <path-to-prominence.md> [<path-to-mcp_cloud_only_tool_schemas.json>]
//     Compares each committed generated file with its source and exits 1 when
//     any block, tool or action differs. The weekly drift workflow runs this
//     against Exomem main.
//
// Home hands these blocks to a Cloud user to paste into an assistant that has no
// Exomem plugin. The doc warns that a shortened capture list silently drops
// whole classes of capture, so the blocks are copied byte for byte, never
// retyped. Sync reads the doc from the repo's HEAD commit, not its working tree,
// so the commit written to the generated file is exactly the text it holds.
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import { format, resolveConfig } from "prettier";
import remarkParse from "remark-parse";
import { unified } from "unified";

const DOC_PATH = "docs/prominence.md";
const OUTPUT_PATH = fileURLToPath(
  new URL("../src/app/exomem/home/instruction-blocks.generated.ts", import.meta.url)
);
const TOOLS_FIXTURE_PATH = "tests/fixtures/mcp_cloud_only_tool_schemas.json";
const TOOLS_OUTPUT_PATH = fileURLToPath(
  new URL("../src/exomem-gateway/cloud-transfer-tools.generated.ts", import.meta.url)
);

// The four levels are a closed set that the doc's own level table fixes, so the
// level word that starts each heading is a sound key. It is not free text.
const LEVELS = ["off", "light", "balanced", "maximal"];

// The Cloud gateway serves exactly these two Exomem commands from the control plane (the
// registry's executor "control_plane"). The names select their fixture entries; the
// actions come from the fixture, so a change in Exomem is a diff here, not a hand edit.
const TRANSFER_TOOLS = ["observe_transfer", "transfer_memory"];

function git(repo, ...args) {
  return execFileSync("git", ["-C", repo, ...args], { encoding: "utf8" });
}

function textOf(node) {
  if (typeof node.value === "string") return node.value;
  return (node.children ?? []).map(textOf).join("");
}

function extractBlocks(markdown) {
  const { children } = unified().use(remarkParse).parse(markdown);
  const blocks = {};

  children.forEach((node, index) => {
    if (node.type !== "heading" || node.depth !== 3) return;
    const level = textOf(node).trim().split(/\s+/)[0].toLowerCase();
    if (!LEVELS.includes(level)) return;
    if (level in blocks) throw new Error(`${DOC_PATH} has two "${level}" level headings`);

    for (const next of children.slice(index + 1)) {
      if (next.type === "heading" && next.depth <= 3) break;
      if (next.type === "code") {
        blocks[level] = next.value;
        return;
      }
    }
    throw new Error(`${DOC_PATH}: the "${level}" heading is not followed by a fenced block`);
  });

  const missing = LEVELS.filter((level) => !blocks[level]);
  if (missing.length > 0) {
    throw new Error(`${DOC_PATH} has no block for: ${missing.join(", ")}`);
  }
  return blocks;
}

function extractTransferTools(fixtureText) {
  const fixture = JSON.parse(fixtureText);
  const tools = {};
  for (const name of TRANSFER_TOOLS) {
    const actions = fixture[name]?.inputSchema?.properties?.action?.enum;
    if (
      !Array.isArray(actions) ||
      actions.length === 0 ||
      actions.some((a) => typeof a !== "string")
    ) {
      throw new Error(`${TOOLS_FIXTURE_PATH} has no action list for ${name}`);
    }
    tools[name] = actions;
  }
  return tools;
}

function renderTransferTools(tools, commit) {
  const entries = TRANSFER_TOOLS.map((name) => `  ${name}: ${JSON.stringify(tools[name])},`);
  return [
    "// Generated by scripts/sync-exomem-instruction-blocks.mjs. Do not edit by hand.",
    "// Regenerate: npm run sync:instruction-blocks -- <path-to-exomem-repo>",
    "",
    "export const CLOUD_TRANSFER_TOOLS_SOURCE = {",
    '  repo: "exomem",',
    `  path: ${JSON.stringify(TOOLS_FIXTURE_PATH)},`,
    `  commit: ${JSON.stringify(commit)},`,
    "} as const;",
    "",
    "export const CLOUD_TRANSFER_TOOLS = {",
    ...entries,
    "} as const;",
    "",
  ].join("\n");
}

function render(blocks, commit) {
  const entries = LEVELS.map((level) => `  ${level}: ${JSON.stringify(blocks[level])},`);
  return [
    "// Generated by scripts/sync-exomem-instruction-blocks.mjs. Do not edit by hand.",
    "// Regenerate: npm run sync:instruction-blocks -- <path-to-exomem-repo>",
    "",
    "export const INSTRUCTION_BLOCKS_SOURCE = {",
    '  repo: "exomem",',
    `  path: ${JSON.stringify(DOC_PATH)},`,
    `  commit: ${JSON.stringify(commit)},`,
    "} as const;",
    "",
    "export const INSTRUCTION_BLOCKS = {",
    ...entries,
    "} as const;",
    "",
  ].join("\n");
}

async function sync(repo) {
  const commit = git(repo, "rev-parse", "HEAD").trim();
  if (!/^[0-9a-f]{40}$/.test(commit)) throw new Error(`unexpected commit from git: ${commit}`);
  // Refuse a feature branch: the recorded commit must be one that Exomem shipped.
  try {
    git(repo, "merge-base", "--is-ancestor", "HEAD", "origin/main");
  } catch {
    throw new Error(
      `exomem HEAD ${commit} is not an ancestor of origin/main; check out main and run git fetch first`
    );
  }
  const blocks = extractBlocks(git(repo, "show", `HEAD:${DOC_PATH}`));
  const tools = extractTransferTools(git(repo, "show", `HEAD:${TOOLS_FIXTURE_PATH}`));
  // Format with the repo's Prettier so `npm run format:check` accepts the files.
  for (const [path, text] of [
    [OUTPUT_PATH, render(blocks, commit)],
    [TOOLS_OUTPUT_PATH, renderTransferTools(tools, commit)],
  ]) {
    const options = await resolveConfig(path);
    writeFileSync(path, await format(text, { ...options, filepath: path }));
  }
  const lengths = LEVELS.map((level) => `${level}=${blocks[level].length}`).join(" ");
  const actions = TRANSFER_TOOLS.map((name) => `${name}=${tools[name].join("|")}`).join(" ");
  console.log(
    `wrote ${OUTPUT_PATH}\n  wrote ${TOOLS_OUTPUT_PATH}\n  exomem ${commit}\n` +
      `  block lengths: ${lengths}\n  transfer tools: ${actions}`
  );
}

async function checkTransferTools(fixtureFile) {
  const expected = extractTransferTools(readFileSync(fixtureFile, "utf8"));
  const { CLOUD_TRANSFER_TOOLS, CLOUD_TRANSFER_TOOLS_SOURCE } = await import(
    pathToFileURL(TOOLS_OUTPUT_PATH).href
  );
  const stale = TRANSFER_TOOLS.filter(
    (name) => JSON.stringify(CLOUD_TRANSFER_TOOLS[name]) !== JSON.stringify(expected[name])
  );
  if (stale.length > 0) {
    throw new Error(
      `transfer tool actions differ from ${fixtureFile} for: ${stale.join(", ")}\n` +
        `  committed copy is from exomem ${CLOUD_TRANSFER_TOOLS_SOURCE.commit}\n` +
        "  run: npm run sync:instruction-blocks -- <path-to-exomem-repo>"
    );
  }
  console.log(
    `transfer tools match ${fixtureFile} (copied from exomem ${CLOUD_TRANSFER_TOOLS_SOURCE.commit})`
  );
}

async function checkBlocks(docFile) {
  const expected = extractBlocks(readFileSync(docFile, "utf8"));
  // Node 24 loads the .ts file by stripping its types, so no build step is needed.
  const { INSTRUCTION_BLOCKS, INSTRUCTION_BLOCKS_SOURCE } = await import(
    pathToFileURL(OUTPUT_PATH).href
  );
  const stale = LEVELS.filter((level) => INSTRUCTION_BLOCKS[level] !== expected[level]);
  if (stale.length > 0) {
    throw new Error(
      `instruction blocks differ from ${docFile} for: ${stale.join(", ")}\n` +
        `  committed copy is from exomem ${INSTRUCTION_BLOCKS_SOURCE.commit}\n` +
        "  run: npm run sync:instruction-blocks -- <path-to-exomem-repo>"
    );
  }
  console.log(
    `instruction blocks match ${docFile} (copied from exomem ${INSTRUCTION_BLOCKS_SOURCE.commit})`
  );
}

// Each source is checked on its own, so one run reports every drifted file.
async function check(docFile, fixtureFile) {
  const checks = [checkBlocks(docFile), ...(fixtureFile ? [checkTransferTools(fixtureFile)] : [])];
  const failed = (await Promise.allSettled(checks)).filter(
    (result) => result.status === "rejected"
  );
  if (failed.length > 0) {
    throw new Error(failed.map((result) => result.reason?.message ?? result.reason).join("\n"));
  }
}

async function main([first, second, third]) {
  if (first === "--check" && second) return check(second, third);
  if (first && !first.startsWith("--")) return sync(first);
  throw new Error(
    "usage: sync-exomem-instruction-blocks.mjs <path-to-exomem-repo>\n" +
      "       sync-exomem-instruction-blocks.mjs --check <path-to-prominence.md> [<path-to-mcp_cloud_only_tool_schemas.json>]"
  );
}

main(process.argv.slice(2)).catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exit(1);
});
